#!/usr/bin/env bash
set -eu
# Before selecting Test, bind the exact saved field hash/time and unchanged policy/cache readback to R4 externally.
exec /usr/bin/python3 - <<'ONIA_R4_BOOTSTRAP'
import base64,gzip,hashlib,subprocess,sys,tempfile
from pathlib import Path
packed = ""
raw=gzip.decompress(base64.b64decode(packed,validate=True))
n=int.from_bytes(raw[:4],"big"); recipe=raw[4:4+n]; manifest=raw[4+n:]
if hashlib.sha256(recipe).hexdigest()!="369f5ddd83e43a102a713baa109dc38bf717107fc341d07d420a2abf67495519": raise SystemExit("BLOCKED: recipe digest mismatch")
if hashlib.sha256(manifest).hexdigest()!="b5f5dd074ab252bbba27b5e02e4eaadc35d92968de2234b21c922b15106e0196": raise SystemExit("BLOCKED: manifest digest mismatch")
with tempfile.TemporaryDirectory(prefix="onia-r4-") as td:
    rp=Path(td)/"setup_recipe.py"; rp.write_bytes(recipe)
    mp=Path(td)/"manifest.json"; mp.write_bytes(manifest)
    subprocess.run([sys.executable,str(rp),"--apply-reviewed-manifest",str(mp)],check=True)
ONIA_R4_BOOTSTRAP
